class NativeUiEncoder final {
 using E=UiEncoderTask;using S=E::Stage;using U=UiEncoderRouteTask;using Q=U::Stage;struct Job{std::variant<E,U>task;unsigned child=0;};
public:struct CodeRange{uint32_t begin,end;};inline static constexpr std::array<CodeRange,2>CodeRanges{{{0x8ba,0x92c},{0x3b6e,0x3bd6}}};bool active()const{return depth_;}void reset(){depth_=0;steps_=0;}uint64_t steps()const{return steps_;}unsigned requestedChild()const{return depth_?jobs_[depth_-1].child:0;}static bool candidate(unsigned at){for(auto r:CodeRanges)if(at>=r.begin&&at<r.end)return true;return false;}
 bool step(Stage1Cpu&c){if(midi_projection::blocked(c))return false;auto at=unsigned(c.getPC());if(!depth_||boundary(jobs_[depth_-1])!=at){Job j;if(at==0x8ba)j.task.emplace<E>();else if(at==0x3b6e)j.task.emplace<U>();else return false;if(depth_==jobs_.size())throw std::logic_error("Native K UI encoder capacity");jobs_[depth_++]=j;}
 auto&j=jobs_[depth_-1];if(auto*t=std::get_if<U>(&j.task))if(t->awaiting())t->resume(uint8_t(c.reg8(14)),uint8_t(c.reg8(t->stage()==Q::SelectParameter?9:8)));j.child=0;if(at!=boundary(j))throw std::logic_error("Native K UI encoder boundary");if(c.pending_irqs)c.read8(0xfffff2);auto len=bytes(j);auto cr=credits(j,c,len);auto cost=std::visit([&](const auto&t){return t.nextClocks(cr);},j.task);auto begin=c.cycles;c.fetchClocks(len);c.pc=c.makepc(at+1);project(j,c);
 if(auto*t=std::get_if<E>(&j.task))t->advanceBefore(cost,cr,[&](E::Read r){unsigned reg=r==E::Read::Counter?6:r==E::Read::Half?13:r==E::Read::Acceleration?5:r==E::Read::Quarter?14:6;if(r==E::Read::Counter){c.reg16(reg)=int16_t(c.read16(0xffff7c));val(c,c.reg16(reg));return unsigned(uint16_t(c.reg16(reg)));}c.reg8(reg)=c.read8(int(readAddress(r)));val(c,c.reg8(reg));return unsigned(uint8_t(c.reg8(reg)));},[&](E::Write field,unsigned value){unsigned reg=field==E::Write::Half||field==E::Write::Direction?14:field==E::Write::Quarter?6:13;val(c,c.reg8(reg));c.write8(int8_t(value),int(writeAddress(field)));});else{auto&u=std::get<U>(j.task);u.advanceBefore(cost,cr,[&](U::Read r){c.reg8(8)=c.read8(r==U::Read::Mode?0xcd7c:0xcd7f);val(c,c.reg8(8));return uint8_t(c.reg8(8));},[&](U::Write field,unsigned value){unsigned reg=field==U::Write::Selection?0:8;val(c,c.reg8(reg));c.write8(int8_t(value),field==U::Write::Selection?0xcd7f:0xcd7e);});}
 if(c.cycles-begin!=cost)throw std::logic_error("Native K UI encoder clocks differ");if(std::visit([](const auto&t){return t.complete();},j.task))--depth_;else if(!waiting(j))c.pc=c.makepc(boundary(j));++steps_;return true;}
private:static void val(Stage1Cpu&c,int v){midi_projection::val(c,v);}static bool waiting(const Job&j){auto*t=std::get_if<U>(&j.task);return t&&t->awaiting();}static unsigned readAddress(E::Read r){switch(r){case E::Read::Counter:return 0xffff7c;case E::Read::Half:return 0xfffd25;case E::Read::Acceleration:return 0xfffd26;case E::Read::Quarter:return 0xfffd24;case E::Read::Direction:return 0xfffd27;}return 0;}static unsigned writeAddress(E::Write w){switch(w){case E::Write::Half:return 0xfffd25;case E::Write::Acceleration:return 0xfffd26;case E::Write::Quarter:return 0xfffd24;case E::Write::Direction:return 0xfffd27;}return 0;}
 static unsigned boundary(const Job&j){if(auto*t=std::get_if<E>(&j.task)){static constexpr unsigned a[]={0x8ba,0x8be,0x8c0,0x8c6,0x8cc,0x8ce,0x8d0,0x8d2,0x8d8,0x8da,0x8dc,0x8de,0x8e0,0x8e2,0x8e4,0x8ea,0x8ec,0x8ee,0x8f0,0x8f2,0x8f4,0x8f6,0x8f8,0x8fe,0x904,0x906,0x908,0x90e,0x914,0x916,0x918,0x91a,0x920,0x922,0x924,0x926,0x928,0x92a,0};return a[unsigned(t->stage())];}auto&t=std::get<U>(j.task);static constexpr unsigned a[]={0x3b6e,0x3b72,0x3b74,0x3b76,0x3b7a,0x3b7c,0x3b82,0x3b84,0x3b86,0x3b8c,0x3b8e,0x3b90,0x3b92,0x3b96,0x3b98,0x3b9a,0x3b9c,0x3b9e,0x3ba4,0x3ba8,0x3baa,0x3bac,0x3bb0,0x3bb4,0x3bba,0x3bbc,0x3bbe,0x3bc0,0x3bc4,0x3bc8,0x3bcc,0x3bce,0x3bd0,0x3bd4,0};return a[unsigned(t.stage())];}
 static unsigned bytes(const Job&j){if(auto*t=std::get_if<E>(&j.task)){switch(t->stage()){case S::ReadCounter:return 4;case S::ReadHalfHistory:case S::WriteHalfHistory:case S::ReadAcceleration:case S::WriteAcceleration:case S::ReadQuarterHistory:case S::WriteQuarterHistory:case S::ReadDirection:case S::WriteDirection:case S::WriteClearedAcceleration:return 6;default:return 2;}}switch(std::get<U>(j.task).stage()){case Q::ReadEncoder:case Q::Gate:case Q::SelectFifth:case Q::DisplayTail:case Q::Edit:case Q::EditTail:case Q::ParameterTail:case Q::Mode:case Q::SelectParameter:case Q::DefaultTail:return 4;case Q::ReadMode:case Q::WriteSelection:case Q::WriteDirection:case Q::ReadSelection:return 6;default:return 2;}}
 static unsigned bus(unsigned at,unsigned n,int last){unsigned cost=0;for(unsigned i=0;i<n;++i){auto a=(at+i)&0xffffff;if(a<0x400000||(a>=0xfffd10&&a<0xffffa0)){if((last&1)||a!=unsigned(last|1))cost+=a<0x400000?3:1;last=int(a);}else{cost+=a>=0xffffa0?1:3;last=-1;}}return cost;}
 static FlashCredits credits(const Job&j,const Stage1Cpu&c,unsigned len){FlashCredits cr;int last=int(c.getPC()+len-1);cr.call=8+bus(c.getSP()-4,4,c.writeHistory());cr.ret=5+bus(c.getSP(),4,last);if(auto*t=std::get_if<E>(&j.task)){switch(t->stage()){case S::ReadCounter:cr.read=bus(readAddress(E::Read::Counter),2,last);break;case S::ReadHalfHistory:cr.read=bus(readAddress(E::Read::Half),1,last);break;case S::ReadAcceleration:cr.read=bus(readAddress(E::Read::Acceleration),1,last);break;case S::ReadQuarterHistory:cr.read=bus(readAddress(E::Read::Quarter),1,last);break;case S::ReadDirection:cr.read=bus(readAddress(E::Read::Direction),1,last);break;case S::WriteHalfHistory:cr.write=bus(writeAddress(E::Write::Half),1,c.writeHistory());break;case S::WriteAcceleration:case S::WriteClearedAcceleration:cr.write=bus(writeAddress(E::Write::Acceleration),1,c.writeHistory());break;case S::WriteQuarterHistory:cr.write=bus(writeAddress(E::Write::Quarter),1,c.writeHistory());break;case S::WriteDirection:cr.write=bus(writeAddress(E::Write::Direction),1,c.writeHistory());break;default:break;}}else{auto&u=std::get<U>(j.task);cr.read=bus(u.stage()==Q::ReadMode?0xcd7c:0xcd7f,1,last);cr.write=bus(u.stage()==Q::WriteSelection?0xcd7f:0xcd7e,1,c.writeHistory());}return cr;}
 static void dec(Stage1Cpu&c,unsigned r){int old=c.reg8(r),v=old-1;val(c,v);if((old&~v)&128)c.ccr|=2;c.reg8(r)=int8_t(v);}static void inc(Stage1Cpu&c,unsigned r){int old=c.reg8(r),v=old+1;val(c,v);if((~old&v)&128)c.ccr|=2;c.reg8(r)=int8_t(v);}static void neg(Stage1Cpu&c,unsigned r){c.reg8(r)=int8_t(midi_projection::arithmetic(c,0,uint8_t(c.reg8(r)),8,true));}static void call(Job&j,Stage1Cpu&c,unsigned target,unsigned returned){j.child=target;midi_projection::call(c,target,returned,true);}
 static void project(Job&j,Stage1Cpu&c){if(auto*t=std::get_if<E>(&j.task)){switch(t->stage()){case S::HalfCounter:case S::QuarterCounter:{unsigned v=uint16_t(c.reg16(6));c.ccr=uint8_t((c.ccr&~1)|(v&1));c.reg16(6)=int16_t(v>>1);val(c,c.reg16(6));break;}case S::DifferenceHalf:c.reg8(13)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(13)),uint8_t(c.reg8(14)),8,true));break;case S::NegateHalf:case S::NegateGain:neg(c,13);break;case S::AddAcceleration:c.reg8(13)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(13)),uint8_t(c.reg8(5)),8,false));break;case S::DecrementAcceleration:dec(c,13);break;case S::CompareAcceleration:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(13)),13,8,true);break;case S::ClampAcceleration:c.reg8(13)=13;val(c,13);break;case S::BiasValue:c.reg8(5)=4;val(c,4);break;case S::SubtractBias:c.reg8(13)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(13)),uint8_t(c.reg8(5)),8,true));break;case S::ClampBias:case S::ClearAcceleration:c.reg8(13)=0;val(c,0);break;case S::IncrementGain:case S::IncrementAfterDirection:inc(c,13);break;case S::CopyQuarter:c.reg8(6)=c.reg8(14);val(c,c.reg8(6));break;case S::DifferenceQuarter:c.reg8(14)=int8_t(midi_projection::arithmetic(c,uint8_t(c.reg8(14)),uint8_t(c.reg8(6)),8,true));break;case S::CompareDirection:c.reg8(6)^=c.reg8(14);val(c,c.reg8(6));break;case S::TestDirection:val(c,c.reg8(14));break;case S::PublishDelta:c.reg8(14)=c.reg8(13);val(c,c.reg8(14));break;case S::Return:midi_projection::ret(c);break;default:break;}}
 else{auto&u=std::get<U>(j.task);switch(u.stage()){case Q::ReadEncoder:call(j,c,0x8ba,0x3b72);break;case Q::TestDelta:case Q::TestSign:val(c,c.reg8(14));break;case Q::Gate:call(j,c,0x4534,0x3b7a);break;case Q::ClearSelection:c.reg8(0)=0;val(c,0);break;case Q::CompareFirst:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(8)),1,8,true);break;case Q::CompareFifth:(void)midi_projection::arithmetic(c,uint8_t(c.reg8(8)),5,8,true);break;case Q::SelectFifth:c.clockI(2);if(u.mode()!=5)c.pc=c.makepc(0x496a);break;case Q::FirstDirection:c.reg8(8)=1;val(c,1);break;case Q::SecondDirection:c.reg8(8)=2;val(c,2);break;case Q::DisplayTail:case Q::EditTail:c.clockI(2);c.pc=c.makepc(0x496a);break;case Q::CopyEditDelta:case Q::CopyParameterDelta:case Q::CopyDefaultDelta:c.reg8(6)=c.reg8(14);val(c,c.reg8(6));break;case Q::EditControl:case Q::ParameterControl:case Q::DefaultControl:c.reg8(14)=int8_t(0xf0);val(c,c.reg8(14));break;case Q::Edit:call(j,c,0x481a,0x3bb0);break;case Q::ParameterTail:c.clockI(2);c.pc=c.makepc(0x4062);break;case Q::Mode:call(j,c,0x40b0,0x3bc8);break;case Q::SelectParameter:c.clockI(2);if(u.parameter())c.pc=c.makepc(0x45aa);break;case Q::DefaultTail:c.clockI(2);c.pc=c.makepc(0x481a);break;case Q::Return:midi_projection::ret(c);break;default:break;}}
 }
 std::array<Job,8>jobs_{};unsigned depth_=0;uint64_t steps_=0;
};
